import { Group, Mesh, PlaneGeometry, Color, Vector2, DoubleSide, Texture } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, smoothstep, vec3, float, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'hub-pricing-card-0-label:pricing2-label';

  const colors = config.intent?.visualSpec?.colors ?? config.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const accentColor = new Color(colors.accent);

  // --- geometry sized to atlas region aspect ratio (512x320 = 1.6:1) ---
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const planeHeight = 0.72;
  const planeWidth = planeHeight * aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

  // --- dynamic grain texture node (placeholder until async load resolves) ---
  const placeholderTex = new Texture();
  const grainTexNode = texture(placeholderTex);

  const uvNode = uv();

  // engineered vertical gradient: surface (top) -> ink (bottom)
  const gradientColor = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), uvNode.y);

  // subtle grain overlay, low opacity blend
  const grainAmount = uniform(0.12);
  const grainBlended = mix(gradientColor, gradientColor.mul(grainTexNode.rgb), grainAmount);

  // thin accent underline near bottom of the plate
  const lineBand = smoothstep(0.0, 0.02, uvNode.y).mul(float(1.0).sub(smoothstep(0.02, 0.045, uvNode.y)));
  const withAccent = mix(grainBlended, vec3(accentColor.r, accentColor.g, accentColor.b), lineBand);

  const material = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });
  material.colorNode = withAccent;
  material.opacity = 1.0;

  const plate = new Mesh(geometry, material);
  plate.name = 'pricing2-label-plate';
  group.add(plate);

  // load grain texture asynchronously through the cached loader
  let disposed = false;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    if (disposed) return;
    tex.wrapS = tex.wrapT = 1000; // RepeatWrapping value (avoids importing THREE constants directly)
    grainTexNode.value = tex;
    material.needsUpdate = true;
  }).catch(() => {
    // no-op: gradient still renders without grain
  });

  // --- text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [{ text: 'Pricing 2', role: 'headline', typography: { fontSize: 39 } }];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const labelText = headlineItem?.text ?? 'Pricing 2';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const textNode = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: colors.paper,
    align: 'center',
    maxWidthPx: rectW * 0.86,
  });
  textNode.position.set(0, 0, 0.002);
  group.add(textNode);

  // --- entrance motion: weighted fade-up settle, no linear easing, subtle translate ---
  group.scale.set(0.98, 0.98, 0.98);
  material.opacity = 0;
  const startY = group.position.y; // adapter applies scenePosition after return; animate local offset instead
  plate.position.y = -0.12;
  textNode.position.y -= 0.12;

  const tl = gsap.timeline();
  tl.to(material, { opacity: 1, duration: 0.6, ease: 'power2.out' });
  tl.to([plate.position, textNode.position], { y: '+=0.12', duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0.05);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    gsap.killTweensOf(material);
    gsap.killTweensOf(plate.position);
    gsap.killTweensOf(textNode.position);
    gsap.killTweensOf(group.scale);

    geometry.dispose();
    material.dispose();
    if (placeholderTex) placeholderTex.dispose();
    if (grainTexNode.value && grainTexNode.value.dispose) grainTexNode.value.dispose();

    if (textNode.userData?.cleanup) {
      textNode.userData.cleanup();
    } else if (textNode.geometry || textNode.material) {
      textNode.geometry?.dispose?.();
      textNode.material?.dispose?.();
    }

    group.clear();
  };

  return group;
}
